        return 0 <= x < w and 0 <= y < h

    def bfs_dist(x0, y0):
        INF = 10**9
        dist = [[INF] * h for _ in range(w)]
        if not inb(x0, y0) or (x0, y0) in obstacles:
            return dist
        dist[x0][y0] = 0
        qx, qy = [x0], [y0]
        qi = 0
        steps = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]
        while qi < len(qx):
            x, y = qx[qi], qy[qi]
            qi += 1
            d = dist[x][y] + 1
            for dx, dy in steps:
                nx, ny = x + dx, y + dy
                if inb(nx, ny) and (nx, ny) not in obstacles and d < dist[nx][ny]:
                    dist[nx][ny] = d
                    qx.append(nx); qy.append(ny)
        return dist

    if not resources:
        return [0, 0]

    INF = 10**9
    d_op = bfs_dist(ox, oy)
    best_move = [0, 0]
    best_val = -10**30

